    topic: Annotated[
        str,
        Field(
            description="The brand, product, person or event to analyze, as a short term. For example `Levi's` or `Running shoes`. Keep it under five words. Do not write a question: every run reports sentiment, price, quality, competitors and products for the topic. To narrow the posts, use `content_filters`.",
            min_length=1,
        ),
    ]
    analysis_scope: Annotated[
        list[Literal["CONTENT", "COMMENT"]] | None,
        Field(
            description='What to analyze: any of `CONTENT`, `COMMENT`. Defaults to `["CONTENT"]`.'
        ),
    ] = ["CONTENT"]
    content_filters: Annotated[
        ContentFilterInputRequest,
        Field(
            description="Selects which content the analysis runs over. At least one of `search`, `creator_id`, `creator_username`, `external_id`, or `brand_id` is required to scope it. When both `posted_after` and `posted_before` are omitted, the analysis defaults to content from the last 7 days."
        ),
    ]


